import{_ as o,o as t,c as s,a2 as i}from"./chunks/framework.BEUshCVJ.js";const d=JSON.parse('{"title":"Audio and devices","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/audio.md","filePath":"troubleshooting/audio.md","lastUpdated":1793129889000}'),n={name:"troubleshooting/audio.md"};function r(a,e,l,h,c,p){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="audio-and-devices" tabindex="-1">Audio and devices <a class="header-anchor" href="#audio-and-devices" aria-label="Permalink to &quot;Audio and devices&quot;">​</a></h1><p>This page helps when MeetCue doesn&#39;t hear you or the other participants, or hears the wrong thing. Open <strong>Settings › Audio › Test levels</strong> to watch both level bars while you work through the steps.</p><h2 id="no-system-sound" tabindex="-1">The system sound level stays flat <a class="header-anchor" href="#no-system-sound" aria-label="Permalink to &quot;The system sound level stays flat {#no-system-sound}&quot;">​</a></h2><p><strong>Possible causes</strong></p><ol><li>The meeting app plays through a different device than the Windows default output.</li><li>Nothing is playing, or the meeting app is muted.</li><li>Another program holds the output device in exclusive mode (<a href="/meetcue/troubleshooting/error-codes#mc-aud-001">MC-AUD-001</a>).</li><li>The audio driver doesn&#39;t support loopback capture (<a href="/meetcue/troubleshooting/error-codes#mc-aud-005">MC-AUD-005</a>).</li></ol><p><strong>Check</strong></p><ol><li>Open <strong>Settings › System › Sound</strong> in Windows and note the output device.</li><li>In your meeting app&#39;s audio settings, check which speaker it uses.</li><li>Play a video in a browser and watch the system sound bar.</li></ol><p><strong>Fix</strong></p><ol><li>Set the meeting app&#39;s speaker to <strong>Default</strong> or to the same device as the Windows output.</li><li>If MeetCue reports MC-AUD-001: open <strong>Sound › More sound settings</strong>, open the device&#39;s <strong>Properties › Advanced</strong>, clear <strong>Allow applications to take exclusive control of this device</strong>, and restart the program that held the device.</li><li>Update the audio driver from your computer manufacturer.</li></ol><div class="tip custom-block"><p class="custom-block-title">Test with headphones</p><p>When you test with speakers, the microphone picks up the sound and its bar moves. That doesn&#39;t mean system sound capture works. Mute the speakers or use headphones and watch the system sound bar only. <code>MeetCue.exe --self-test</code> checks exactly this.</p></div><p><strong>Still not solved?</strong> <a href="/meetcue/troubleshooting/diagnostics">Export diagnostics</a> and <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">open an issue</a>.</p><h2 id="no-microphone" tabindex="-1">The microphone level stays flat <a class="header-anchor" href="#no-microphone" aria-label="Permalink to &quot;The microphone level stays flat {#no-microphone}&quot;">​</a></h2><p><strong>Possible causes</strong></p><ol><li>Windows blocks microphone access for desktop apps (<a href="/meetcue/troubleshooting/error-codes#mc-aud-002">MC-AUD-002</a>).</li><li>MeetCue uses a different microphone from the one you speak into.</li><li>The microphone is muted by a hardware key or in the meeting app&#39;s driver.</li></ol><p><strong>Check</strong></p><ol><li>Open <strong>Settings › Privacy &amp; security › Microphone</strong> in Windows.</li><li>In MeetCue, open <strong>Settings › Audio</strong> and look at <strong>Microphone (you)</strong>.</li></ol><p><strong>Fix</strong></p><ol><li>Turn on <strong>Microphone access</strong> and <strong>Let desktop apps access your microphone</strong>.</li><li>Choose your microphone in <strong>Microphone (you)</strong>, or choose <strong>System default</strong> and set the default in Windows.</li><li>Press the laptop&#39;s microphone mute key if its light is on.</li></ol><p><strong>Still not solved?</strong> <a href="/meetcue/troubleshooting/diagnostics">Export diagnostics</a> and <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">open an issue</a>.</p><h2 id="device-changed" tabindex="-1">Capture stops after changing headphones or speakers <a class="header-anchor" href="#device-changed" aria-label="Permalink to &quot;Capture stops after changing headphones or speakers {#device-changed}&quot;">​</a></h2><p><strong>Possible causes</strong></p><ol><li>The default device changed and capture is restarting (<a href="/meetcue/troubleshooting/error-codes#mc-aud-004">MC-AUD-004</a>).</li><li>The new device is in use exclusively by another program.</li></ol><p><strong>Check</strong></p><ol><li>Look for the &quot;The audio device changed; capture restarted&quot; notice in the panel.</li><li>Watch the level bars for a few seconds after the change.</li></ol><p><strong>Fix</strong></p><ol><li>Wait two or three seconds; MeetCue rebuilds capture on its own.</li><li>If the bars stay flat, pause and resume with <code>Ctrl+Alt+Space</code>.</li></ol><p><strong>Still not solved?</strong> <a href="/meetcue/troubleshooting/diagnostics">Export diagnostics</a> and <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">open an issue</a>.</p><h2 id="quiet-voices" tabindex="-1">Questions from soft-spoken participants are missed <a class="header-anchor" href="#quiet-voices" aria-label="Permalink to &quot;Questions from soft-spoken participants are missed {#quiet-voices}&quot;">​</a></h2><p><strong>Possible causes</strong></p><ol><li>The participant&#39;s voice reaches your computer much quieter than the others, below the system sound voice threshold, so it isn&#39;t sent for recognition.</li><li><strong>Boost quiet voices from the meeting</strong> is off, so the recognizer gets the voice too quiet to transcribe reliably.</li><li>The meeting app&#39;s own volume for that participant, or its output volume, is turned down.</li></ol><p><strong>Check</strong></p><ol><li>Open <strong>Settings › Audio</strong>, click <strong>Test levels</strong>, and watch the system sound bar while that person speaks. Note the level in dB.</li><li>Compare it with <strong>Settings › Audio › Advanced › System sound voice threshold</strong>.</li></ol><p><strong>Fix</strong></p><ol><li>Turn on <strong>Boost quiet voices from the meeting</strong> (on by default). It raises soft voices to a normal speaking level before recognition and never changes your microphone.</li><li>Lower <strong>System sound voice threshold</strong> to about 5 dB below the level you saw. The default, −60 dBFS, catches almost every voice; raise it only if music or background noise in the meeting gets transcribed.</li><li>Turn the participant&#39;s volume up in the meeting app.</li></ol><p><strong>Still not solved?</strong> <a href="/meetcue/troubleshooting/diagnostics">Export diagnostics</a> and <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">open an issue</a>.</p><h2 id="echo" tabindex="-1">The other side&#39;s words tick off my points <a class="header-anchor" href="#echo" aria-label="Permalink to &quot;The other side&#39;s words tick off my points {#echo}&quot;">​</a></h2><p><strong>Possible causes</strong></p><ol><li>You use speakers, so the microphone picks up the other participants.</li><li>The microphone is very sensitive or close to the speakers.</li></ol><p><strong>Check</strong></p><ol><li>Look at the conversation: lines marked <strong>Me</strong> that repeat what someone else just said.</li></ol><p><strong>Fix</strong></p><ol><li>Use headphones. This is the most reliable fix.</li><li>Turn the speaker volume down, or move the microphone away from the speakers.</li><li>Raise <strong>Settings › Audio › Advanced › Microphone voice threshold</strong> a little.</li></ol><p><strong>Still not solved?</strong> <a href="/meetcue/troubleshooting/diagnostics">Export diagnostics</a> and <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">open an issue</a>.</p><h2 id="bluetooth" tabindex="-1">Playback sounds worse with a Bluetooth headset <a class="header-anchor" href="#bluetooth" aria-label="Permalink to &quot;Playback sounds worse with a Bluetooth headset {#bluetooth}&quot;">​</a></h2><p><strong>Possible causes</strong></p><ol><li>When an app opens a Bluetooth headset&#39;s microphone, Windows switches the headset to its call mode, which has lower sound quality for everything.</li></ol><p><strong>Check</strong></p><ol><li><strong>Settings › Audio</strong> shows a warning when the selected microphone looks like a Bluetooth device.</li></ol><p><strong>Fix</strong></p><ol><li>Choose the computer&#39;s built-in microphone in <strong>Microphone (you)</strong> and keep the headset for listening.</li></ol><p><strong>Still not solved?</strong> <a href="/meetcue/troubleshooting/diagnostics">Export diagnostics</a> and <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">open an issue</a>.</p>',51)])])}const g=o(n,[["render",r]]);export{d as __pageData,g as default};
